      "ref": "customer = {'name': '', 'age': -2, 'email': 'bad_email'}\nclass BatchValidationError(Exception):\n    def __init__(self, errors):\n        super().__init__('; '.join(errors))\n        self.errors = errors\n\ndef validate_customer(c):\n    errs = []\n    if not c.get('name'):\n        errs.append('name is empty')\n    if c.get('age', 0) < 0:\n        errs.append('age is negative')\n    if '@' not in c.get('email', ''):\n        errs.append('email missing @')\n    if errs:\n        raise BatchValidationError(errs)\n    return c\n\ntry:\n    validate_customer(customer)\nexcept BatchValidationError as e:\n    error_count = len(e.errors)\n    all_errors = e.errors\n",
